INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.iacr')=(SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.iacr' AND package='com.samsung.tv.iacr' AND app_component='svcapp' AND app_exec='/opt/usr/apps/com.samsung.tv.iacr/bin/iacr' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'false' AND app_support_disable IS 'false');
