INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.farfieldvoice')=(SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.farfieldvoice' AND package='com.samsung.tv.farfieldvoice' AND app_component='svcapp' AND app_exec='/opt/usr/apps/com.samsung.tv.farfieldvoice/bin/ffv-service' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'true' AND app_support_disable IS 'false');
