INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='org.tizen.voice-app')=(SELECT count(*) FROM package_app_info WHERE app_id='org.tizen.voice-app' AND package='org.tizen.voice-app' AND app_component='uiapp' AND app_exec='/opt/usr/apps/org.tizen.voice-app/bin/voice-app' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'false' AND app_support_disable IS 'false');
