INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.bixby-prov')=(SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.bixby-prov' AND package='com.samsung.tv.bixby-prov' AND app_component='svcapp' AND app_exec='/opt/usr/apps/com.samsung.tv.bixby-prov/bin/bixby-prov' AND app_disable IS 'true' AND app_onboot IS 'true' AND app_autorestart IS 'true' AND app_support_disable IS 'false');
