INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.alexa-fullscreen-app')=(SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.alexa-fullscreen-app' AND package='com.samsung.tv.alexa-client' AND app_component='uiapp' AND app_exec='/opt/usr/apps/com.samsung.tv.alexa-client/bin/alexa-fullscreen-app' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'false' AND app_support_disable IS 'false');
INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.wakeup-engine-alexa')=(SELECT count(*) FROM package_app_info WHERE app_id='com.samsung.tv.wakeup-engine-alexa' AND package='com.samsung.tv.wakeup-engine-alexa' AND app_component='svcapp' AND app_exec='/opt/usr/apps/com.samsung.tv.wakeup-engine-alexa/bin/wakeup-engine-alexa' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'true' AND app_support_disable IS 'false');
INSERT INTO quiet_guard SELECT (SELECT count(*) FROM package_app_info WHERE app_id='AQKO41xyKP.AmazonAlexa')=(SELECT count(*) FROM package_app_info WHERE app_id='AQKO41xyKP.AmazonAlexa' AND package='AQKO41xyKP' AND app_component='uiapp' AND app_exec='/opt/usr/apps/AQKO41xyKP/bin/AQKO41xyKP.AmazonAlexa' AND app_disable IS 'true' AND app_onboot IS 'false' AND app_autorestart IS 'false' AND app_support_disable IS 'false');
INSERT INTO quiet_guard SELECT count(*)=0 FROM package_app_info_for_uid WHERE app_id IN ('com.samsung.tv.acr','com.samsung.tv.iacr','com.samsung.tv.contents-recognition-dbmgr','com.samsung.tv.contents-cognition-dbmgr','com.samsung.tv.farfieldvoice','com.samsung.tv.ondevice-voice','com.samsung.tv.voiceid-service','org.tizen.voice-client','org.tizen.stt-client','org.tizen.voice-app','org.tizen.voice-app-service','com.samsung.tv.wakeup-engine-bixby','com.samsung.tv.bixby-prov','com.samsung.tv.voiceassistant-music','com.samsung.tv.vif','com.samsung.tv.alexa-client','com.samsung.tv.alexa-fullscreen-app','com.samsung.tv.wakeup-engine-alexa','AQKO41xyKP.AmazonAlexa');
